/* eslint-disable */
// @ts-nocheck — generated by catalog-eject; runtime-correct but TS strict-mode false-positives on inlined catalog body
import React, { useState } from 'react';
import ScrollReveal from "@/components/ui/ScrollReveal";
import TextAnimation from "@/components/ui/TextAnimation";

const ContactInline = () => {
  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    telefono: '',
    empresa: '',
    comentarios: '',
  });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e: any) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: any) => {
    e.preventDefault();
    const subject = encodeURIComponent(`Solicitud de Demostración - ${formData.nombre || 'Lead'}`);
    const body = encodeURIComponent(
      `Nombre: ${formData.nombre}\n` +
      `Email: ${formData.email}\n` +
      `Teléfono: ${formData.telefono}\n` +
      `Empresa: ${formData.empresa}\n\n` +
      `Comentarios:\n${formData.comentarios}`
    );
    
    window.location.href = `mailto:hola@renexa.es?subject=${subject}&body=${body}`;
    setSubmitted(true);
  };

  return (
    <section aria-label="Contact section" className="py-20">
      <div className="w-content-width mx-auto">
        <ScrollReveal variant="slide-up">
          <div className="flex flex-col items-center gap-8 py-12 px-6 sm:px-12 rounded card max-w-3xl mx-auto">
            <div className="flex flex-col items-center gap-2 text-center w-full">
              <div className="px-3 py-1 mb-1 text-sm card rounded w-fit">
                <p className="text-xs uppercase tracking-wider text-accent">Solicitar Demostración</p>
              </div>

              <TextAnimation
                text={"¿Listo para escalar tu empresa?"}
                variant={"slide-up"}
                gradientText={true}
                tag="h2"
                className="text-3xl sm:text-4xl font-semibold text-center text-balance mb-2"
              />

              <p className="text-accent text-sm sm:text-base max-w-lg mb-2">
                Déjanos tus datos y comentarios para coordinar tu demostración personalizada.
              </p>
            </div>

            {submitted ? (
              <div className="w-full text-center py-8 px-6 card rounded-lg border border-primary-cta/30">
                <h3 className="text-xl font-bold text-foreground mb-2">¡Solicitud generada!</h3>
                <p className="text-accent text-sm mb-4">
                  Se ha preparado el correo con tus datos dirigido a <strong>hola@renexa.es</strong>.
                </p>
                <button
                  type="button"
                  onClick={() => setSubmitted(false)}
                  className="secondary-button text-sm px-4 py-2 cursor-pointer"
                >
                  Enviar otra solicitud
                </button>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="w-full flex flex-col gap-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="flex flex-col gap-1.5 text-left">
                    <label htmlFor="nombre" className="text-xs font-medium text-foreground">
                      Nombre completo *
                    </label>
                    <input
                      type="text"
                      id="nombre"
                      name="nombre"
                      required
                      value={formData.nombre}
                      onChange={handleChange}
                      placeholder="Ej. María García"
                      className="w-full px-4 py-2.5 rounded border border-white/10 bg-background text-foreground text-sm focus:outline-none focus:border-primary-cta transition-colors"
                    />
                  </div>

                  <div className="flex flex-col gap-1.5 text-left">
                    <label htmlFor="email" className="text-xs font-medium text-foreground">
                      Correo electrónico *
                    </label>
                    <input
                      type="email"
                      id="email"
                      name="email"
                      required
                      value={formData.email}
                      onChange={handleChange}
                      placeholder="maria@empresa.com"
                      className="w-full px-4 py-2.5 rounded border border-white/10 bg-background text-foreground text-sm focus:outline-none focus:border-primary-cta transition-colors"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="flex flex-col gap-1.5 text-left">
                    <label htmlFor="telefono" className="text-xs font-medium text-foreground">
                      Teléfono
                    </label>
                    <input
                      type="tel"
                      id="telefono"
                      name="telefono"
                      value={formData.telefono}
                      onChange={handleChange}
                      placeholder="+34 600 000 000"
                      className="w-full px-4 py-2.5 rounded border border-white/10 bg-background text-foreground text-sm focus:outline-none focus:border-primary-cta transition-colors"
                    />
                  </div>

                  <div className="flex flex-col gap-1.5 text-left">
                    <label htmlFor="empresa" className="text-xs font-medium text-foreground">
                      Empresa
                    </label>
                    <input
                      type="text"
                      id="empresa"
                      name="empresa"
                      value={formData.empresa}
                      onChange={handleChange}
                      placeholder="Nombre de tu empresa"
                      className="w-full px-4 py-2.5 rounded border border-white/10 bg-background text-foreground text-sm focus:outline-none focus:border-primary-cta transition-colors"
                    />
                  </div>
                </div>

                <div className="flex flex-col gap-1.5 text-left">
                  <label htmlFor="comentarios" className="text-xs font-medium text-foreground">
                    Comentarios o preguntas *
                  </label>
                  <textarea
                    id="comentarios"
                    name="comentarios"
                    required
                    rows={4}
                    value={formData.comentarios}
                    onChange={handleChange}
                    placeholder="Cuéntanos qué solución necesitas para tu empresa..."
                    className="w-full px-4 py-2.5 rounded border border-white/10 bg-background text-foreground text-sm focus:outline-none focus:border-primary-cta transition-colors resize-none"
                  />
                </div>

                <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mt-2">
                  <div className="flex items-center gap-2 text-xs text-accent">
                    <span>O escríbenos directamente a:</span>
                    <a href="mailto:hola@renexa.es" className="hover:text-foreground underline">hola@renexa.es</a>
                  </div>
                  <button
                    type="submit"
                    className="primary-button text-sm px-6 py-3 w-full sm:w-auto text-center cursor-pointer"
                  >
                    Solicitar demostración
                  </button>
                </div>
              </form>
            )}
          </div>
        </ScrollReveal>
      </div>
    </section>
  );
};

export default function ContactSection() {
  return (
    <div data-webild-section="contact" data-section="contact" id="contact">
      <ContactInline />
    </div>
  );
}
